<?php
require_once __DIR__ . '/../assets/php/layout.php';
$period=(string)($_GET['period']??'week');if(!in_array($period,['week','month','year'],true))$period='week';
$span=$period==='week'?'7 DAY':($period==='month'?'30 DAY':'365 DAY');
$rows=[];$error='';
try{$pdo=db();$device=get_active_device($pdo);if($device){$sql="SELECT DATE(measured_at) AS day, COUNT(*) AS readings, ROUND(AVG(temperature_c),1) AS avg_temp, ROUND(AVG(humidity_pct),1) AS avg_humidity, MIN(temperature_c) AS min_temp, MAX(temperature_c) AS max_temp FROM readings WHERE device_id=? AND measured_at >= UTC_TIMESTAMP() - INTERVAL {$span} GROUP BY DATE(measured_at) ORDER BY day DESC";$stmt=$pdo->prepare($sql);$stmt->execute([$device['id']]);$rows=$stmt->fetchAll();}}catch(Throwable $exception){$error=database_error_message();}
if(($_GET['export']??'')==='docx'&&!$error){
 if(!class_exists(ZipArchive::class)){http_response_code(503);exit('DOCX export requires PHP ZipArchive. Enable the zip extension in XAMPP PHP.');}
 $esc=static fn(string $value):string=>htmlspecialchars($value,ENT_XML1|ENT_QUOTES,'UTF-8');
 $paragraph=static function(string $text,int $size=22,bool $bold=false,string $color='26372B',int $after=120)use($esc):string{return '<w:p><w:pPr><w:spacing w:after="'.$after.'"/></w:pPr><w:r><w:rPr><w:color w:val="'.$color.'"/><w:sz w:val="'.$size.'"/>'.($bold?'<w:b/>':'').'</w:rPr><w:t xml:space="preserve">'.$esc($text).'</w:t></w:r></w:p>';};
 $cell=static function(string $text,bool $header=false)use($paragraph):string{return '<w:tc><w:tcPr><w:tcW w:w="1800" w:type="auto"/>'.($header?'<w:shd w:fill="285C3B"/>':'').'</w:tcPr>'.$paragraph($text,$header?18:17,$header,$header?'FFFFFF':'26372B',40).'</w:tc>';};
 $table='<w:tbl><w:tblPr><w:tblBorders><w:top w:val="single" w:sz="4" w:color="C9D8CD"/><w:left w:val="single" w:sz="4" w:color="C9D8CD"/><w:bottom w:val="single" w:sz="4" w:color="C9D8CD"/><w:right w:val="single" w:sz="4" w:color="C9D8CD"/><w:insideH w:val="single" w:sz="4" w:color="C9D8CD"/><w:insideV w:val="single" w:sz="4" w:color="C9D8CD"/></w:tblBorders></w:tblPr><w:tblGrid>'.str_repeat('<w:gridCol w:w="1800"/>',6).'</w:tblGrid><w:tr>'.implode('',array_map(static fn($v)=>$cell($v,true),['Date (UTC)','Readings','Avg temp','Min temp','Max temp','Avg humidity'])).'</w:tr>';
 foreach($rows as $row){$table.='<w:tr>'.implode('',array_map(static fn($v)=>$cell((string)$v),[$row['day'],$row['readings'],$row['avg_temp']===null?'—':$row['avg_temp'].' °C',$row['min_temp']===null?'—':$row['min_temp'].' °C',$row['max_temp']===null?'—':$row['max_temp'].' °C',$row['avg_humidity']===null?'—':$row['avg_humidity'].' %'])).'</w:tr>';}
 $table.='</w:tbl>';
 $total=array_sum(array_map(static fn($row)=>(int)$row['readings'],$rows));$range=$rows?min(array_column($rows,'day')).' to '.max(array_column($rows,'day')):'No readings in this period';
 $body=$paragraph('Environment Monitoring Report',34,true,'285C3B',260).$paragraph(ucfirst($period).' summary',26,true,'26372B',180).$paragraph('Device: '.($device['name']??$device['location']??'No device selected')).$paragraph('Reporting coverage (UTC): '.$range).$paragraph('Generated (UTC): '.gmdate('Y-m-d H:i:s')).$paragraph('At a glance',24,true,'285C3B',120).$paragraph('Total readings: '.$total).$paragraph('Days with readings: '.count($rows),22,false,'26372B',240).$paragraph('Daily readings',24,true,'285C3B',120).$table.$paragraph('Temperature and humidity values are calculated from the device readings received during each UTC day.',18,false,'66756B',0);
 $document='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'.$body.'<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1000" w:right="900" w:bottom="1000" w:left="900"/></w:sectPr></w:body></w:document>';
 $temp=tempnam(sys_get_temp_dir(),'env-report-');$zip=new ZipArchive();if($zip->open($temp,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true){@unlink($temp);http_response_code(500);exit('Could not create the DOCX report.');}
 $zip->addFromString('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');
 $zip->addFromString('_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');$zip->addFromString('word/document.xml',$document);$zip->close();
 header('Content-Type: application/vnd.openxmlformats-officedocument.wordprocessingml.document');header('Content-Disposition: attachment; filename="environment-report-'.$period.'-'.gmdate('Y-m-d').'.docx"');header('Content-Length: '.filesize($temp));readfile($temp);@unlink($temp);exit;
}
layout_start('Reports','reports');
?>
<section class="content-card"><div class="section-heading"><div><h2><?= e(ucfirst($period)) ?> report</h2><p>Daily averages from readings received in the selected period.</p></div><div class="report-actions"><nav class="segmented" aria-label="Report period"><?php foreach(['week'=>'7 days','month'=>'30 days','year'=>'1 year'] as $key=>$label): ?><a class="<?= $period===$key?'selected':'' ?>" href="?period=<?= e($key) ?>"><?= e($label) ?></a><?php endforeach; ?></nav><?php if(!$error&&$rows): ?><a class="button-primary small" href="?period=<?= e($period) ?>&amp;export=docx">Export DOCX</a><?php endif; ?></div></div>
<?php if($error): ?><p class="inline-notice"><?= e($error) ?></p><?php elseif(!$rows): ?><p class="empty-state">Reports will be available when the device has uploaded readings.</p><?php else: ?><p class="chart-legend">Coverage: <?= e(min(array_column($rows,'day'))) ?> to <?= e(max(array_column($rows,'day'))) ?> UTC · <?= array_sum(array_map(static fn($row)=>(int)$row['readings'],$rows)) ?> readings across <?= count($rows) ?> days.</p><div class="table-scroll"><table><thead><tr><th>Date (UTC)</th><th>Readings</th><th>Avg temp</th><th>Min temp</th><th>Max temp</th><th>Avg humidity</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['day']) ?></td><td><?= (int)$row['readings'] ?></td><td><?= $row['avg_temp']===null?'—':e((string)$row['avg_temp']).' °C' ?></td><td><?= $row['min_temp']===null?'—':e((string)$row['min_temp']).' °C' ?></td><td><?= $row['max_temp']===null?'—':e((string)$row['max_temp']).' °C' ?></td><td><?= $row['avg_humidity']===null?'—':e((string)$row['avg_humidity']).' %' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
<?php layout_end(); ?>

